"""Shared frame generator for brand/docs/screens/*.html (used by the batch build scripts)."""
ICONS=[('Home','<svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z" fill="currentColor"/></svg>'),
 ('Trades','<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M4 19v-7M10 19V6M16 19v-4M21 19v-9"/></svg>'),
 ('Rulebook','<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h9M4 12h9M4 18h6M16 16.5l2 2 4-4.5"/></svg>'),
 ('Performance','<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 17l5.5-6 4 3.5L21 6"/></svg>')]
def tabs(on): return '<nav class="rq-tabs" aria-label="Main">'+''.join(f'<a class="rq-tab" href="#" {"aria-current=\"page\"" if on==k else ""}>{i}<span>{k}</span></a>' for k,i in ICONS)+'</nav>'
SBAR='<div class="sbar"><span>9:41</span><div class="sbar__ic"><i></i><i></i><i></i></div><div class="sbar__b"></div></div>'
GEAR='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--rq-ink-soft)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>'
TOP='<div class="top"><span class="top__brand"><svg width="22" height="22" viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="11.25" fill="none" stroke="currentColor" stroke-width="2.4"/><circle cx="19.8" cy="19" r="3.3" fill="var(--rq-accent)"/></svg>Retrospeq</span>'+GEAR+'</div>'
SUBNAV=lambda on: '<nav class="rq-pills" aria-label="Rulebook">'+''.join(f'<a class="rq-pill{" on" if on==k else ""}" href="#">{k}</a>' for k in ['Rules','Strategies','Fields'])+'</nav>'
def frame(num,title,body,cap,tab=None,shell=True,scroll=False):
    inner=(TOP if shell else '')+f'<div class="sb{" sb--scroll" if scroll else ""}">{body}</div>'+(tabs(tab) if tab else '')
    return f'<div class="ex" id="{num}"><div class="ex__t"><b>{num}</b> {title}</div><div class="phone"><div class="scr">{SBAR}{inner}</div></div><p class="cap">{cap}</p></div>'
def page(title,sub,sections):
    body=''.join(f'<p class="rq-label sect"{" style=\"margin-top:0\"" if i==0 else ""}>{h}</p><div class="gal">{"".join(fr)}</div>' for i,(h,fr) in enumerate(sections))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>Retrospeq — Screens · {title}</title><link rel="icon" href="../../logo/favicon.svg"><link rel="stylesheet" href="../../css/index.css"><link rel="stylesheet" href="frame.css"></head><body><div class="page">
<div class="bar"><div><h1>{title}</h1><p class="rq-sub">{sub}</p></div><button class="tbtn" id="themeBtn" type="button">Theme: system</button></div>{body}</div><script>(function(){{var r=document.documentElement,b=document.getElementById('themeBtn'),s=['system','light','dark'],i=0;b.onclick=function(){{i=(i+1)%3;if(s[i]==='system')delete r.dataset.theme;else r.dataset.theme=s[i];b.textContent='Theme: '+s[i];}};}})();</script></body></html>'''
DOTS=lambda on,off,size=7: f'<div class="rq-dots" style="--rq-dot-size:{size}px">'+'<i></i>'*on+'<i class="off"></i>'*off+'</div>'
